import 'package:drift/drift.dart';

import '../database/app_database.dart';

ExercisesCompanion _ex(
  String id,
  String name,
  String category,
  String? equipment,
  String movementType,
  List<String> muscleGroups,
  bool isCompound,
  String description,
  String now,
) {
  return ExercisesCompanion(
    exerciseId: Value(id),
    name: Value(name),
    category: Value(category),
    equipment: Value(equipment),
    movementType: Value(movementType),
    muscleGroups: Value('[${muscleGroups.map((g) => '"$g"').join(',')}]'),
    isCompound: Value(isCompound),
    description: Value(description),
    isUserCustom: const Value(false),
    createdAt: Value(now),
  );
}

